// Página do gerador de clipes de vídeo por IA (LTX-Video no Hugging Face).
// ── Moldura das páginas (mesmo visual em todos os fluxos grátis) ──
function pagina(titulo, corpo, script) {
  const css = `
:root{--fundo:#f6f5f2;--cartao:#fff;--texto:#1d1d1b;--suave:#6b6b66;--linha:#e3e1db;--acento:#0f766e;--acento2:#115e59;--erro:#b42318;--ok:#067647}
@media (prefers-color-scheme:dark){:root{--fundo:#121412;--cartao:#1b1e1c;--texto:#ecebe7;--suave:#a3a39d;--linha:#2c302d;--acento:#2dd4bf;--acento2:#5eead4;--erro:#f97066;--ok:#47cd89}}
*{box-sizing:border-box}body{margin:0;background:var(--fundo);color:var(--texto);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:20px 16px 48px}h1{font-size:1.45rem;margin:.2em 0 .1em}h2{font-size:1.1rem;margin:1.2em 0 .5em}
.sub{color:var(--suave);margin:0 0 18px}.cartao{background:var(--cartao);border:1px solid var(--linha);border-radius:14px;padding:16px;margin:12px 0}
label{display:block;font-weight:600;margin:12px 0 6px}textarea,input,select{width:100%;padding:11px 12px;border:1px solid var(--linha);border-radius:10px;background:var(--fundo);color:var(--texto);font:inherit}
textarea{min-height:120px;resize:vertical}.linha{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
button,.botao{display:inline-block;background:var(--acento);color:#fff;border:0;border-radius:10px;padding:12px 18px;font:600 1rem system-ui,sans-serif;cursor:pointer;text-decoration:none;margin-top:14px}
@media (prefers-color-scheme:dark){button,.botao{color:#04211e}}
button[disabled]{opacity:.55;cursor:wait}.botao.sec{background:transparent;color:var(--acento);border:1px solid var(--acento)}
.aviso{color:var(--suave);font-size:.9rem}.erro{color:var(--erro);font-weight:600}.ok{color:var(--ok);font-weight:600}
.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.grade img,.grade video{width:100%;border-radius:10px;border:1px solid var(--linha);background:#000}
video,audio{width:100%;margin-top:10px;border-radius:10px}pre{white-space:pre-wrap;background:var(--fundo);border:1px solid var(--linha);border-radius:10px;padding:12px;font-size:.9rem}
.barra{height:8px;background:var(--linha);border-radius:99px;overflow:hidden;margin:10px 0}.barra i{display:block;height:100%;background:var(--acento);width:0;transition:width .6s}
.selo{display:inline-block;font-size:.78rem;border:1px solid var(--linha);border-radius:99px;padding:2px 9px;color:var(--suave);margin:2px 4px 2px 0}
footer{color:var(--suave);font-size:.82rem;margin-top:28px}`;
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="robots" content="noindex"><title>' + titulo + '</title><style>' + css + '</style></head><body><main>' + corpo +
    '<footer>Feito com serviços grátis e sem chave (Hugging Face, Pollinations, Bing/Google Tradutor). Pode demorar ou falhar quando eles estão cheios.</footer>' +
    '</main>' + (script ? '<script>' + script + '</script>' : '') + '</body></html>';
}
const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const corpo = `
<h1>🎥 Clipes de vídeo por IA, grátis</h1>
<p class="sub">Texto → vídeo ou foto → vídeo com o LTX-Video (Hugging Face), sem chave. Clipes de 2 a 5 s, qualidade
abaixo do Veo. A cota grátis acaba depois de alguns clipes por dia.</p>
<div class="cartao">
  <label for="prompt">O que acontece na cena</label>
  <textarea id="prompt" maxlength="800" placeholder="Ex.: drone sobrevoando uma casa com placas solares ao pôr do sol">drone sobrevoando uma casa moderna com placas solares no telhado ao pôr do sol, cinematográfico</textarea>
  <label for="foto">Foto para animar (opcional)</label>
  <input id="foto" type="file" accept="image/*">
  <div class="linha">
    <div><label for="formato">Formato</label><select id="formato"><option value="9:16">Vertical 9:16</option>
      <option value="16:9">Deitado 16:9</option><option value="1:1">Quadrado</option></select></div>
    <div><label for="dur">Duração</label><select id="dur"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></div>
    <div><label for="melhorar">Melhorar o pedido com IA</label><select id="melhorar"><option value="1">Sim</option><option value="0">Não</option></select></div>
  </div>
  <button id="ir">Gerar clipe</button>
  <p id="estado" class="aviso"></p>
  <video id="video" controls loop playsinline hidden></video>
  <a id="baixar" class="botao sec" hidden download="clipe.mp4">Baixar MP4</a>
</div>
<div class="cartao aviso">Outros fluxos: <code>POST</code> aqui com <code>{"prompt":"...","formato":"9:16","duracao":3}</code>
(ou <code>"foto_b64"</code> com a foto em base64) → <code>{"id":"...","status":"..."}</code> na hora; consulte o
<code>status</code> até vir <code>{"etapa":"pronto","url":"..."}</code> (ou <code>"erro"</code>). O link vale 7 dias.</div>`;
const script = `
const $ = id => document.getElementById(id);
function fotoReduzida(arq) {
  return new Promise((ok, falha) => {
    const img = new Image();
    img.onload = () => {
      const m = Math.min(1, 1024 / Math.max(img.width, img.height));
      const c = document.createElement('canvas'); c.width = Math.round(img.width * m); c.height = Math.round(img.height * m);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
      ok(c.toDataURL('image/jpeg', 0.88));
    };
    img.onerror = () => falha(new Error('não consegui abrir a foto'));
    img.src = URL.createObjectURL(arq);
  });
}
// Plano B: a cota grátis do Hugging Face é por IP. Quando a do servidor acaba, o mesmo pedido sai daqui do navegador
// (IP de quem está usando, cota própria). O Space libera chamadas desta página (CORS).
const HF = 'https://lightricks-ltx-video-distilled.hf.space/gradio_api';
const NEG = 'worst quality, inconsistent motion, blurry, jittery, distorted, watermark, text, subtitles';
async function peloNavegador(s, corpo) {
  $('estado').dataset.extra = ' — a cota grátis do servidor acabou; gerando pelo seu navegador';
  const [w, h] = { '9:16': [480, 832], '16:9': [832, 480], '1:1': [640, 640] }[corpo.formato] || [480, 832];
  let rota = 'text_to_video', foto = null;
  if (corpo.foto_b64) {
    const fd = new FormData();
    fd.append('files', await (await fetch(corpo.foto_b64)).blob(), 'foto.jpg');
    const up = await (await fetch(HF + '/upload', { method: 'POST', body: fd })).json();
    if (!Array.isArray(up) || !up[0]) throw new Error('não consegui mandar a foto ao Hugging Face');
    foto = { path: up[0], orig_name: 'foto.jpg', meta: { _type: 'gradio.FileData' } };
    rota = 'image_to_video';
  }
  const dados = [s.prompt || corpo.prompt, NEG, foto, null, h, w, foto ? 'image-to-video' : 'text-to-video', corpo.duracao, 9, 42, true, 1, true];
  const ev = await (await fetch(HF + '/call/' + rota, { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ data: dados }) })).json();
  if (!ev.event_id) throw new Error('o Hugging Face não aceitou o pedido agora; tente mais tarde');
  const txt = await (await fetch(HF + '/call/' + rota + '/' + ev.event_id)).text();
  const ultima = txt.split('\\n').filter(l => l.startsWith('data:')).pop() || '';
  let url = null;
  try { const d = JSON.parse(ultima.slice(5)); url = txt.includes('event: complete') && d[0] && d[0].video && d[0].video.url; } catch (e) {}
  if (!url) throw new Error('a cota grátis do Hugging Face acabou (no servidor e neste aparelho); tente daqui a algumas horas');
  return { url: URL.createObjectURL(await (await fetch(url)).blob()), prompt_usado: s.prompt_usado };
}
$('ir').onclick = async () => {
  $('ir').disabled = true; $('video').hidden = true; $('baixar').hidden = true; $('estado').className = 'aviso';
  $('estado').dataset.extra = '';
  const t0 = Date.now();
  const relogio = setInterval(() => { $('estado').textContent = 'Gerando o clipe... ' + Math.round((Date.now() - t0) / 1000) + ' s (de 15 s a 3 min)' + ($('estado').dataset.extra || ''); }, 1000);
  try {
    const arq = $('foto').files[0];
    const corpo = { prompt: $('prompt').value.trim(), formato: $('formato').value, duracao: Number($('dur').value),
      melhorar: $('melhorar').value === '1' };
    if (arq) corpo.foto_b64 = await fotoReduzida(arq);
    const r = await fetch(location.pathname, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corpo) });
    const p = await r.json();
    if (!p.ok) throw new Error(p.erro || 'falhou');
    // o pedido volta na hora com o código; aqui a página consulta o andamento até o clipe sair (uma consulta que falhar só repete)
    let j = null, falhas = 0;
    while (!j) {
      await new Promise(ok => setTimeout(ok, 3000));
      if (Date.now() - t0 > 12 * 60 * 1000) throw new Error('demorou demais; tente de novo mais tarde');
      try {
        const s = await (await fetch(location.pathname + '-status?id=' + encodeURIComponent(p.id), { cache: 'no-store' })).json();
        falhas = 0;
        if (s.etapa === 'pronto') j = s;
        else if (s.etapa === 'erro' && !s.cota) throw Object.assign(new Error(s.erro || 'falhou'), { doFluxo: true });
        else if (s.etapa === 'erro') j = await peloNavegador(s, corpo).catch(e => { throw Object.assign(e, { doFluxo: true }); });
      } catch (e) {
        if (e.doFluxo || ++falhas > 20) throw e;
      }
    }
    $('video').src = j.url; $('video').hidden = false; $('video').play().catch(() => {});
    $('baixar').href = j.url; $('baixar').hidden = false;
    $('estado').className = 'ok'; $('estado').textContent = 'Pronto em ' + Math.round((Date.now() - t0) / 1000) + ' s' + (j.prompt_usado ? ' — pedido usado: ' + j.prompt_usado : '');
  } catch (e) {
    $('estado').className = 'erro';
    $('estado').textContent = 'Não deu: ' + (e.message === 'Failed to fetch' ? 'a conexão caiu; confira a internet e tente de novo' : e.message);
  }
  clearInterval(relogio); $('ir').disabled = false;
};`;
return [{ json: { html: pagina('Clipes de vídeo grátis', corpo, script) } }];

// Confere o pedido na hora (sem IA) para responder logo com o código; a geração continua depois da resposta.
const ent = $input.first().json;
const b = ent.body || {};
const h = ent.headers || {};
const base = (h['x-forwarded-proto'] || 'https') + '://' + (h['x-forwarded-host'] || h.host);
const prompt = String(b.prompt || '').replace(/\s+/g, ' ').trim().slice(0, 800);
const temFoto = !!b.foto_b64;
if (!prompt && !temFoto) return [{ json: { ok: false, erro: 'Descreva a cena ou mande uma foto.' } }];
const formato = ['9:16', '16:9', '1:1'].includes(b.formato) ? b.formato : '9:16';
const dur = Math.max(2, Math.min(5, Number(b.duracao) || 3));
const [w, hh] = { '9:16': [480, 832], '16:9': [832, 480], '1:1': [640, 640] }[formato];
let foto = null;
if (temFoto) {
  foto = Buffer.from(String(b.foto_b64).replace(/^data:[^,]+,/, ''), 'base64');
  if (foto.length < 1000 || foto.length > 6e6) return [{ json: { ok: false, erro: 'A foto precisa ter entre 1 KB e 6 MB.' } }];
}
const id = Date.now().toString(36) + require('crypto').randomBytes(3).toString('hex');
const item = { json: { ok: true, id, base, prompt, melhorar: b.melhorar !== false, tem_foto: temFoto, w, hh, dur,
  status: base + '/webhook/gratis-clipe-status?id=' + id } };
if (foto) item.binary = { data: await this.helpers.prepareBinaryData(foto, 'foto.jpg', 'image/jpeg') };
return [item];

// Melhora o texto da cena com IA grátis (depois da resposta à página). A foto segue como arquivo para o nó HTTP subir ao Space.
// ── Texto por IA grátis e sem chave (Pollinations, modelo openai-fast) ──
// Limite sem chave: 1 resposta a cada 30 s por IP. Quem chama em sequência precisa esperar (nó ⏳ de 31 s).
// Sem chave o "response_format" dá 400: o JSON é pedido no texto e lido com lerJson (tolera ```json e texto em volta).
// O modelo grátis "pensa" antes de responder: sem reasoning_effort low ele estoura o limite e devolve 400
// (output_token_limit_exceeded); "minimal" não existe e "medium" também estoura.
async function perguntaIA(helpers, mensagens, emJson = false, tentativas = 1) {
  let ultimo = '';
  for (let t = 0; t < tentativas; t++) {
    try {
      const r = await helpers.httpRequest({ method: 'POST', url: 'https://text.pollinations.ai/openai', json: true, timeout: 50000,
        // seed aleatória: sem ela o Pollinations devolve do cache a MESMA resposta para o mesmo pedido
        body: { model: 'openai', messages: mensagens, reasoning_effort: 'low', max_tokens: 6000, seed: Math.floor(Math.random() * 1e9) } });
      const txt = r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
      if (txt) return emJson ? lerJson(txt) : String(txt).trim();
      ultimo = 'resposta vazia';
    } catch (e) {
      ultimo = String((e.response && e.response.body && JSON.stringify(e.response.body)) || e.message || e).slice(0, 200);
    }
  }
  throw new Error('IA grátis (Pollinations) não respondeu: ' + ultimo);
}

function lerJson(txt) {
  const s = String(txt).replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try { return JSON.parse(s); } catch (e) { /* tenta achar o bloco */ }
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) return JSON.parse(s.slice(i, j + 1));
  throw new Error('a IA não devolveu JSON');
}

const c = $('🧩 Confere o pedido').first();
let prompt = c.json.prompt;
let usado = '';
if (c.json.melhorar && prompt) {
  try {
    usado = await perguntaIA(this.helpers, [
      { role: 'system', content: 'You write prompts for a text-to-video model (LTX-Video). Translate to English and ' +
        'describe ONE continuous shot in max 50 words: subject, action/motion, camera movement, lighting, style. ' +
        'No text, captions or logos. Answer only the prompt.' },
      { role: 'user', content: prompt }]);
    usado = usado.replace(/^["']|["']$/g, '').slice(0, 600);
    if (usado.length > 10) prompt = usado; else usado = '';
  } catch (e) { usado = ''; }
}
if (!prompt) prompt = 'smooth cinematic camera movement, subtle natural motion, high quality';
const item = { json: { ...c.json, prompt, prompt_usado: usado } };
if (c.binary) item.binary = c.binary;
return [item];

// Monta a chamada do LTX-Video: texto → vídeo, ou foto → vídeo com o caminho da foto já enviada ao Space.
// ── Spaces do Hugging Face pela API pública do Gradio (sem chave; cota grátis por IP) ──
// Chamada curta (cabe nos 60 s do Code). Para espera longa, use dois nós HTTP: POST .../call/<rota> e
// GET .../call/<rota>/<event_id> (texto), e depois gradioLe() num Code.
async function gradioChama(helpers, espaco, rota, dados, limite = 50000) {
  const base = 'https://' + espaco + '.hf.space/gradio_api/call/' + rota;
  const r = await helpers.httpRequest({ method: 'POST', url: base, body: { data: dados }, json: true, timeout: 20000 });
  const ev = r && r.event_id;
  if (!ev) throw new Error(espaco + ': sem event_id');
  return gradioLe(String(await helpers.httpRequest({ url: base + '/' + ev, timeout: limite, json: false })), espaco);
}

// Lê a resposta (SSE) da 2ª chamada: devolve o JSON final ou dá erro com o motivo.
function gradioLe(txt, espaco = 'Hugging Face') {
  txt = String(txt || '');
  if (!txt.includes('event: complete')) {
    const m = /event: error\s*\ndata: (.*)/.exec(txt);
    const motivo = m && m[1] !== 'null' ? m[1].slice(0, 200) : 'recusou (a cota grátis do Hugging Face acabou ou a fila está cheia; tente mais tarde)';
    throw new Error(espaco + ': ' + motivo);
  }
  const linhas = txt.split('\n').filter(l => l.startsWith('data:'));
  return JSON.parse(linhas[linhas.length - 1].slice(5));
}

const urlDe = d => { const m = /"url":\s*"([^"]+)"/.exec(JSON.stringify(d)); return m ? m[1] : null; };

// Arquivos para o Space: o Gradio não aceita link de fora nem base64 nas entradas de arquivo, só o caminho de um
// upload (POST .../gradio_api/upload, multipart). O upload tem que ser pelo nó HTTP do n8n (n8nlib.http_envia_arquivo):
// o httpRequest do Code manda o binário como UTF-8 e estraga o arquivo (testado 30/10: 512 bytes viraram 768).
const arquivoGradio = (caminho, nome) => ({ path: caminho, orig_name: nome, meta: { _type: 'gradio.FileData' } });
function caminhoDoUpload(txt) {
  try { const l = JSON.parse(String(txt || '')); return Array.isArray(l) && l[0] ? l[0] : null; } catch (e) { return null; }
}

const p = $('🧩 Prepara o pedido').first().json;
const ESPACO = 'lightricks-ltx-video-distilled';
const NEG = 'worst quality, inconsistent motion, blurry, jittery, distorted, watermark, text, subtitles';
let rota = 'text_to_video';
let dados = [p.prompt, NEG, null, null, p.hh, p.w, 'text-to-video', p.dur, 9, 42, true, 1, true];
if (p.tem_foto) {
  const caminho = caminhoDoUpload(($('🌐 Sobe a foto').first().json || {}).data);
  if (!caminho) return [{ json: { ok: false, erro: 'Não consegui mandar a foto ao Hugging Face agora. Tente de novo.' } }];
  rota = 'image_to_video';
  dados = [p.prompt, NEG, arquivoGradio(caminho, 'foto.jpg'), null, p.hh, p.w, 'image-to-video', p.dur, 9, 42, true, 1, true];
}
return [{ json: { ok: true, rota, url_chamada: 'https://' + ESPACO + '.hf.space/gradio_api/call/' + rota, corpo: { data: dados } } }];

// Lê a resposta do LTX-Video e baixa o MP4 (fica no Redis por 7 dias).
// ── Spaces do Hugging Face pela API pública do Gradio (sem chave; cota grátis por IP) ──
// Chamada curta (cabe nos 60 s do Code). Para espera longa, use dois nós HTTP: POST .../call/<rota> e
// GET .../call/<rota>/<event_id> (texto), e depois gradioLe() num Code.
async function gradioChama(helpers, espaco, rota, dados, limite = 50000) {
  const base = 'https://' + espaco + '.hf.space/gradio_api/call/' + rota;
  const r = await helpers.httpRequest({ method: 'POST', url: base, body: { data: dados }, json: true, timeout: 20000 });
  const ev = r && r.event_id;
  if (!ev) throw new Error(espaco + ': sem event_id');
  return gradioLe(String(await helpers.httpRequest({ url: base + '/' + ev, timeout: limite, json: false })), espaco);
}

